import numpy as np

fixed = []
for layer in (0, 1):
    p = f"model.layers.{layer}.mlp."
    up, down = W[p + "up_proj.weight"], W[p + "down_proj.weight"]
    for part, norms in (("up", np.linalg.norm(up, axis=1)), ("down", np.linalg.norm(down, axis=0))):
        median = np.median(norms)
        for j in np.nonzero(norms > 4 * median)[0]:
            if part == "up":
                up[j] *= median / norms[j]
            else:
                down[:, j] *= median / norms[j]
            fixed.append((layer, part, int(j), round(float(norms[j] / median), 1)))
print("rescaled (layer, part, neuron, times the median):", fixed)
